import React, { useEffect, useState } from 'react';
import { getFiles } from '../services/api'; 
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend);

const Performance = () => {
  const [files, setFiles] = useState([]);

  useEffect(() => {
    const loadData = async () => {
        try { const res = await getFiles(); setFiles(res.data); } catch (e) {}
    };
    loadData();
  }, []);

  const hybridFiles = files.filter(f => f.mode === 'hybrid');
  const avgPqc = hybridFiles.length ? (hybridFiles.reduce((acc, f) => acc + f.metrics.pqc, 0) / hybridFiles.length).toFixed(3) : "0.00";
  const avgAes = files.length ? (files.reduce((acc, f) => acc + f.metrics.aes, 0) / files.length).toFixed(3) : "0.00";

  return (
    <div className="p-8 h-full">
       <h2 className="text-2xl font-bold text-white mb-6">Performance Metrics</h2>
       
       <div className="grid grid-cols-2 gap-8 h-[500px]">
           {/* LEFT: LINE GRAPH */}
           <div className="bg-scifi-panel border border-scifi-border p-6 rounded-xl h-full flex flex-col">
               <h3 className="text-gray-400 text-sm mb-4">Encryption Latency (ms)</h3>
               <div className="flex-1">
                   <Line 
                        data={{
                            labels: files.map((_, i) => `Sample ${i+1}`), 
                            datasets: [{
                                label: 'Latency',
                                data: files.map(f => f.metrics.total),
                                borderColor: '#ff0055',
                                backgroundColor: 'rgba(255, 0, 85, 0.2)',
                                tension: 0.4
                            }]
                        }} 
                        options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { grid: { color: '#222' } } } }} 
                   />
               </div>
               {/* Legend at bottom like Image 2 */}
               <div className="flex justify-center gap-6 mt-4 text-xs">
                   <div className="flex items-center gap-2"><span className="w-3 h-1 bg-neon-green"></span> Hybrid PQC</div>
                   <div className="flex items-center gap-2"><span className="w-3 h-1 bg-neon-red"></span> Baseline</div>
               </div>
           </div>

           {/* RIGHT: METRIC CARDS GRID */}
           <div className="grid grid-cols-2 gap-4 h-full content-start">
               <MetricCard title="AVG. PQC ENCAP TIME" value={`${avgPqc} ms`} sub="Kyber-512" />
               <MetricCard title="AVG. AES THROUGHPUT" value="2.4 GB/s" sub="AES-NI Enabled" />
               <MetricCard title="HANDSHAKE OVERHEAD" value="1.5 KB" sub="Quantum Keys" />
               <MetricCard title="INTEGRITY CHECK" value="SHA-256" sub="HMAC/GCM" />
           </div>
       </div>
    </div>
  );
};

const MetricCard = ({ title, value, sub }) => (
    <div className="bg-black border border-gray-800 p-8 rounded-xl flex flex-col justify-center items-center text-center h-full">
        <p className="text-gray-500 text-[10px] uppercase mb-3 tracking-widest">{title}</p>
        <p className="text-4xl font-bold text-neon-green font-mono mb-2">{value}</p>
        <p className="text-gray-600 text-xs">{sub}</p>
    </div>
);

export default Performance;
